export const CloneInfoSchema = z.object({
  home_location: z.object({
    location_id: z.number(),
    location_type: z.enum(['station', 'structure']),
  }).passthrough().optional(),
  jump_clones: z.array(z.object({
    jump_clone_id: z.number(),       // REQUIRED
    location_id: z.number(),          // REQUIRED
    location_type: z.enum(['station', 'structure']),  // REQUIRED
    implants: z.array(z.number()),    // REQUIRED
    name: z.string().optional(),      // optional
  }).passthrough()),
  last_clone_jump_date: z.string().optional(),
  last_station_change_date: z.string().optional(),
}).passthrough();
```

The schema requires all those fields in the jump_clones array, and I'm checking what the mock response data looks like to see if it's providing all the required fields.

